class Account{void displayDetails(){}}class SavingsAccount extends Account{void displayDetails(){System.out.println("Savings Account");}}class CurrentAccount extends Account{void displayDetails(){System.out.println("Current Account");}}interface Payment{void pay(double a);}interface SecurePayment extends Payment{void verifyPayment();}class UPIPayment implements SecurePayment{public void pay(double a){System.out.println("UPI "+a);}public void verifyPayment(){System.out.println("Verified");}}class CardPayment implements Payment{public void pay(double a){System.out.println("Card "+a);}}interface OnlineTransaction{}public class OnlineBankingSystem{public static void main(String[]x){Account a=new SavingsAccount();a.displayDetails();Payment p=new UPIPayment();p.pay(500);((SecurePayment)p).verifyPayment();}}